"""Pure layout title formatting and validation, with no model/service imports.

Callers supply an object exposing the presentation fields. Django's standalone
ValidationError preserves the existing validation contract without using the ORM.
Models and alias-saving services depend on this leaf, never the reverse.
"""

import re
import unicodedata
from uuid import UUID

from django.core.exceptions import ValidationError


DISPLAY_NAME_MAX_LENGTH = 160
_UUID = r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
# Strip only the suffix formats actually generated by ingestion/segmentation.
# Deliberately retain other bracketed text (e.g. [East] or [AI concept]).
_GENERATED_SUFFIX = re.compile(
    rf"\s*\[(?:(?:AI|manual) {_UUID}|(?:ai|script|manual) segment [0-9a-f]{{8}})\]$",
    re.IGNORECASE,
)
_BHK = re.compile(r"(\d+(?:\.\d+)?)\s*BHK", re.IGNORECASE)
_UNSAFE_CATEGORIES = {"Cc", "Cf", "Cs", "Zl", "Zp"}


def _safe_text(value):
    """Plain display text, not HTML; renderers must retain normal escaping."""
    return "".join(
        " " if unicodedata.category(char) in _UNSAFE_CATEGORIES else char
        for char in (value or "")
    ).strip()


def clean_layout_name(plan_name):
    """Remove known trailing generated IDs, without rewriting meaningful names."""
    name = _safe_text(plan_name)
    while True:
        cleaned = _GENERATED_SUFFIX.sub("", name).rstrip()
        if cleaned == name:
            break
        name = cleaned
    try:
        UUID(name)
    except ValueError:
        return name
    return ""


def layout_display_title(plan):
    alias = _safe_text(plan.display_name)
    if alias:
        return alias
    name = clean_layout_name(plan.plan_name)
    if name:
        return name
    configuration = _BHK.fullmatch(_safe_text(plan.configuration_type))
    title = f"{configuration.group(1)} BHK layout" if configuration else "Floor plan" if plan.plan_scope == "floor" else "Layout"
    if plan.page_number:
        return f"{title} — page {plan.page_number}"
    return title if configuration else "Floor plan"


def validate_layout_display_name(value):
    """Validate before trimming so controls or oversized input never disappear."""
    if not isinstance(value, str):
        raise ValidationError({"display_name": "Enter a layout name or an empty string to clear it."})
    if len(value) > DISPLAY_NAME_MAX_LENGTH:
        raise ValidationError({"display_name": "Layout names must be at most 160 characters."})
    if any(unicodedata.category(char) in _UNSAFE_CATEGORIES for char in value):
        raise ValidationError({"display_name": "Layout names cannot contain control or formatting characters."})
    return value.strip()